{
    "type": "object",
    "properties": {
        "partner_name": {
            "type": "string",
            "description": "Customer/vendor name to search for (fuzzy)."
        }
    },
    "required": ["partner_name"]
}

Partner = env['res.partner']
if 'credit' not in Partner.fields_get(['credit']):
    ai['result'] = "ERROR: The Accounting app is not installed."
elif not partner_name:
    ai['result'] = "ERROR: Provide a partner name."
else:
    partners = Partner.search(['|', ['name', 'ilike', partner_name], ['ref', 'ilike', partner_name]], limit=5)
    if not partners:
        ai['result'] = f"ERROR: No partner found matching '{partner_name}'."
    else:
        currency = env.company.currency_id.name
        lines = [f"Partner balances (company currency {currency}; receivable = they owe us, payable = we owe them):"]
        for p in partners:
            open_docs = env['account.move'].search_count([
                ['partner_id', 'child_of', p.id], ['state', '=', 'posted'],
                ['payment_state', 'in', ['not_paid', 'partial']],
                ['move_type', 'in', ['out_invoice', 'in_invoice']],
            ])
            lines.append(f"  {p.display_name} | receivable: {p.credit} | payable: {p.debit} | open posted docs: {open_docs}")
        ai['result'] = "\n".join(lines)

{
    "type": "object",
    "properties": {
        "partner_name": {
            "type": "string",
            "description": "Optional customer name to restrict the aging to. Empty string for the whole company."
        }
    },
    "required": ["partner_name"]
}

AML = env['account.move.line']
if 'amount_residual' not in AML.fields_get(['amount_residual']):
    ai['result'] = "ERROR: The Accounting app is not installed."
else:
    domain = [
        ['account_id.account_type', '=', 'asset_receivable'],
        ['parent_state', '=', 'posted'],
        ['amount_residual', '!=', 0],
    ]
    partner_note = ""
    partner_error = None
    if partner_name:
        partner = env['res.partner'].search([['name', 'ilike', partner_name]], limit=1)
        if not partner:
            partner_error = f"ERROR: No partner found matching '{partner_name}'."
        else:
            domain.append(['partner_id', 'child_of', partner.id])
            partner_note = f" for {partner.display_name}"
    if partner_error:
        ai['result'] = partner_error
    else:
        records = AML.search_read(domain, ['amount_residual', 'date_maturity', 'date'], limit=5000)
        today = datetime.date.today()
        buckets = {'not_due': 0.0, 'b30': 0.0, 'b60': 0.0, 'b90': 0.0, 'over': 0.0}
        for r in records:
            due = r['date_maturity'] or r['date']
            days = (today - due).days if due else 0
            amount = r['amount_residual']
            if days <= 0:
                buckets['not_due'] += amount
            elif days <= 30:
                buckets['b30'] += amount
            elif days <= 60:
                buckets['b60'] += amount
            elif days <= 90:
                buckets['b90'] += amount
            else:
                buckets['over'] += amount
        currency = env.company.currency_id.name
        ai['result'] = (
            f"Receivable aging{partner_note} ({len(records)} open items, {currency}):\n"
            f"  Not due yet: {round(buckets['not_due'], 2)}\n"
            f"  1-30 days overdue: {round(buckets['b30'], 2)}\n"
            f"  31-60 days: {round(buckets['b60'], 2)}\n"
            f"  61-90 days: {round(buckets['b90'], 2)}\n"
            f"  Over 90 days: {round(buckets['over'], 2)}\n"
            f"  TOTAL open receivable: {round(sum(buckets.values()), 2)}"
        )

{
    "type": "object",
    "properties": {
        "journal_name": {
            "type": "string",
            "description": "Optional bank journal name filter. Empty string for all bank journals."
        }
    },
    "required": ["journal_name"]
}

if 'account.bank.statement.line' not in env:
    ai['result'] = "ERROR: The Accounting app is not installed."
else:
    domain = [['is_reconciled', '=', False]]
    if journal_name:
        domain.append(['journal_id.name', 'ilike', journal_name])
    lines = env['account.bank.statement.line'].search(domain, order='date desc', limit=1000)
    if not lines:
        ai['result'] = "All bank statement lines are reconciled. Nothing pending."
    else:
        total = sum(lines.mapped('amount'))
        currency = env.company.currency_id.name
        out = [f"Unreconciled bank lines: {len(lines)} | total amount: {round(total, 2)} {currency}", "Newest 5:"]
        for l in lines[:5]:
            out.append(f"  {l.date} | {l.payment_ref or l.name or ''} | {l.amount}")
        out.append("Reconciliation must be done manually in Accounting — suggest the user opens the bank reconciliation screen.")
        ai['result'] = "\n".join(out)

{
    "type": "object",
    "properties": {
        "partner_name": {
            "type": "string",
            "description": "Customer name to search for (fuzzy)."
        }
    },
    "required": ["partner_name"]
}

if 'sale.order' not in env:
    ai['result'] = "ERROR: The Sales app is not installed."
else:
    partner = env['res.partner'].search([['name', 'ilike', partner_name]], limit=1)
    if not partner:
        ai['result'] = f"ERROR: No customer found matching '{partner_name}'."
    else:
        orders = env['sale.order'].search([['partner_id', 'child_of', partner.id]], order='date_order desc', limit=10)
        has_delivery_status = 'delivery_status' in env['sale.order'].fields_get(['delivery_status'])
        out = [f"Sales history of {partner.display_name} (last {len(orders)} orders):"]
        for o in orders:
            extra = f" | delivery: {o.delivery_status}" if has_delivery_status and o.delivery_status else ""
            out.append(f"  {o.name} | {o.date_order} | state: {o.state} | total: {o.amount_total} | invoicing: {o.invoice_status}{extra}")
        # Top purchased products (confirmed orders), aggregated in python
        sol = env['sale.order.line'].search_read(
            [['order_id.partner_id', 'child_of', partner.id], ['order_id.state', 'in', ['sale', 'done']], ['product_id', '!=', False]],
            ['product_id', 'product_uom_qty', 'price_unit'], limit=500, order='id desc')
        stats = {}
        for l in sol:
            key = l['product_id'][1]
            if key not in stats:
                stats[key] = {'qty': 0.0, 'last_price': l['price_unit']}
            stats[key]['qty'] += l['product_uom_qty']
        top = sorted(stats.items(), key=lambda kv: kv[1]['qty'], reverse=True)[:5]
        if top:
            out.append("Most purchased products (qty | last price):")
            for name, s in top:
                out.append(f"  {name} | {s['qty']} | {s['last_price']}")
        ai['result'] = "\n".join(out)

{
    "type": "object",
    "properties": {
        "threshold": {
            "type": "number",
            "description": "Fallback threshold: list products with on-hand below this. Use 0 to rely on reordering rules only."
        }
    },
    "required": ["threshold"]
}

if 'stock.warehouse.orderpoint' not in env:
    ai['result'] = "ERROR: The Inventory app is not installed."
else:
    out = []
    orderpoints = env['stock.warehouse.orderpoint'].search([], limit=200)
    below = []
    for op in orderpoints:
        onhand = op.product_id.qty_available
        if onhand < op.product_min_qty:
            below.append(f"  {op.product_id.display_name} | on hand: {onhand} | minimum: {op.product_min_qty} | suggested max: {op.product_max_qty}")
    if below:
        out.append(f"Products BELOW their reorder minimum ({len(below)}):")
        out.extend(below[:20])
    elif orderpoints:
        out.append("All products with reordering rules are above their minimum.")
    if threshold:
        products = env['product.product'].search([['qty_available', '<', float(threshold)], ['type', '=', 'consu']], limit=20)
        if products:
            out.append(f"Products with on-hand below {threshold}:")
            for p in products:
                out.append(f"  {p.display_name} | on hand: {p.qty_available} | incoming: {p.incoming_qty}")
    if not out:
        out.append("No low-stock products found.")
    out.append("To replenish: propose a purchase order DRAFT (confirmation protocol applies); never adjust inventory quantities directly.")
    ai['result'] = "\n".join(out)

{
    "type": "object",
    "properties": {
        "product_name": {
            "type": "string",
            "description": "Product name to look up."
        },
        "vendor_name": {
            "type": "string",
            "description": "Optional vendor name filter. Empty string for all vendors."
        }
    },
    "required": ["product_name", "vendor_name"]
}

if 'product.supplierinfo' not in env:
    ai['result'] = "ERROR: The Purchase app is not installed."
else:
    domain = ['|', ['product_tmpl_id.name', 'ilike', product_name], ['product_id.name', 'ilike', product_name]]
    if vendor_name:
        domain = ['&'] + domain + [['partner_id.name', 'ilike', vendor_name]]
    infos = env['product.supplierinfo'].search(domain, limit=10)
    if not infos:
        ai['result'] = f"No vendor pricelist entries found for '{product_name}'."
    else:
        out = [f"Vendor info for '{product_name}' (price | lead time days | min qty):"]
        for si in infos:
            out.append(f"  {si.partner_id.display_name} | {si.price} {si.currency_id.name} | {si.delay} days | min {si.min_qty}")
        ai['result'] = "\n".join(out)

{
    "type": "object",
    "properties": {
        "employee_name": {
            "type": "string",
            "description": "Employee name. Empty string = the current user's own balance."
        }
    },
    "required": ["employee_name"]
}

if 'hr.leave.allocation' not in env:
    ai['result'] = "ERROR: The Time Off app is not installed."
else:
    if employee_name:
        employee = env['hr.employee'].search([['name', 'ilike', employee_name]], limit=1)
        if not employee:
            ai['result'] = f"ERROR: No employee found matching '{employee_name}' (or you have no access to them)."
            employee = None
    else:
        employee = env.user.employee_id
        if not employee:
            ai['result'] = "ERROR: The current user is not linked to an employee record."
    if employee:
        allocations = env['hr.leave.allocation'].search([
            ['employee_id', '=', employee.id], ['state', '=', 'validate']])
        if not allocations:
            ai['result'] = f"No validated leave allocations found for {employee.name}."
        else:
            per_type = {}
            for alloc in allocations:
                key = alloc.holiday_status_id.name
                per_type.setdefault(key, {'allocated': 0.0, 'type_id': alloc.holiday_status_id.id})
                per_type[key]['allocated'] += alloc.number_of_days
            out = [f"Leave balance of {employee.name} (allocated | taken | remaining, in days):"]
            for type_name, data in per_type.items():
                taken_leaves = env['hr.leave'].search([
                    ['employee_id', '=', employee.id],
                    ['holiday_status_id', '=', data['type_id']],
                    ['state', '=', 'validate']])
                taken = sum(taken_leaves.mapped('number_of_days'))
                out.append(f"  {type_name}: {data['allocated']} | {taken} | {data['allocated'] - taken}")
            ai['result'] = "\n".join(out)

{
    "type": "object",
    "properties": {
        "leave_id": {
            "type": "number",
            "description": "Database ID of the hr.leave request to evaluate."
        }
    },
    "required": ["leave_id"]
}
